Fixpoint tcells (sizes : list nat) (bs : list byte) : list cell :=
  match sizes with
  | [] => []
  | k :: r => (if Nat.eqb k 4 then C4 (le_bytes_to_word (firstn 4 bs))
               else if Nat.eqb k 8 then C8 (le_bytes_to_word (firstn 8 bs)) else CB k (firstn k bs)) :: tcells r (skipn k bs)
  end.
